/**
 * TTOken Code task status card: while the agent works on the Session's message, a card above the composer names the
 * Session's folder and how long the work has run. The time counts from when this window first saw the work running,
 * so a window opened during a long task shows less than the whole run.
 * Generated by ttoken/apply-brand.mjs from ttoken/client/composer/TaskStatus.tsx; edit it there.
 */

import { useEffect, useState, type ReactNode } from 'react'
import type { PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type { SessionId } from '@deepseek-ai/dsh-session/types'
import { pathPartsOf } from '@deepseek-ai/dsh-util-workspace-path'
import type { TTOKEN_COMPOSER_NS } from './locales.ts'
import css from './TaskStatus.module.css'

/** Milliseconds between two updates of the elapsed time. */
const TICK_MS = 1_000

/** When this window first saw each Session's current work running; a Session leaves the map when its work ends. */
const runStarts = new Map<SessionId, number>()

/** Sessions whose card the user hid for the current run. */
const hiddenRuns = new Map<SessionId, number>()

/** Props of the task status card. */
export type TaskStatusProps = PropsRuntime<'conversation.input.dock'> & PropsLocale<typeof TTOKEN_COMPOSER_NS>

/**
 * The task status card, shown while the Session's agent works.
 * @param props - dock props with the Session kit and copy.
 * @returns the card, or null while the agent is idle or the user hid the card for this run.
 */
export function TaskStatus({ session, sessionId, useSessions, useWorkspaces, t }: TaskStatusProps): ReactNode {
  const running = session.running
  const createdIn = useSessions(snapshot => snapshot.byId[sessionId]?.cwd)
  const workspacePath = useWorkspaces(snapshot => snapshot.items.find(item => item.sessionIds.includes(sessionId))?.path)
  const [now, setNow] = useState(() => Date.now())
  const [, setHidden] = useState(0)

  if (running && !runStarts.has(sessionId)) runStarts.set(sessionId, Date.now())
  useEffect(() => {
    if (!running) {
      runStarts.delete(sessionId)
      hiddenRuns.delete(sessionId)
      return undefined
    }
    const timer = window.setInterval(() => { setNow(Date.now()) }, TICK_MS)
    return () => { window.clearInterval(timer) }
  }, [running, sessionId])

  const startedAt = runStarts.get(sessionId)
  if (!running || startedAt === undefined || hiddenRuns.get(sessionId) === startedAt) return null
  const path = createdIn ?? workspacePath
  const folder = path === undefined ? null : pathPartsOf(path).name
  return (
    <div role="status" aria-label={t('task.label')} className={css.card}>
      <MarkGlyph />
      <span className={css.pill}>{t('task.product')}</span>
      <RunningGlyph />
      <span className={css.title}>{folder === null ? t('task.title') : t('task.titleIn', { folder })}</span>
      <span className={css.time}>{t('task.running', { time: elapsedOf(Math.max(0, now - startedAt), t) })}</span>
      <span className={css.spacer} />
      <button
        type="button"
        className={css.hide}
        aria-label={t('task.hide')}
        title={t('task.hide')}
        onClick={() => {
          hiddenRuns.set(sessionId, startedAt)
          setHidden(value => value + 1)
        }}
      >
        <svg width="14" height="14" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" aria-hidden="true">
          <path d="M5.5 5.5l9 9M14.5 5.5l-9 9" />
        </svg>
      </button>
    </div>
  )
}

/** Elapsed time as seconds, minutes, or hours and minutes. */
function elapsedOf(ms: number, t: PropsLocale<typeof TTOKEN_COMPOSER_NS>['t']): string {
  const seconds = Math.floor(ms / 1_000)
  if (seconds < 60) return t('task.seconds', { n: seconds })
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) return t('task.minutes', { n: minutes })
  return t('task.hours', { h: Math.floor(minutes / 60), m: minutes % 60 })
}

/** The TTOken mark. */
function MarkGlyph(): ReactNode {
  return (
    <svg className={css.mark} width="22" height="19" viewBox="0 0 56 48" aria-hidden="true">
      <path d="M8 0H48A8 8 0 0 1 56 8A8 8 0 0 1 48 16H8A8 8 0 0 1 0 8A8 8 0 0 1 8 0ZM15 4A9 9 0 0 1 24 13V39A9 9 0 0 1 15 48A9 9 0 0 1 6 39V13A9 9 0 0 1 15 4ZM41 4A9 9 0 0 1 50 13V21A9 9 0 0 1 41 30A9 9 0 0 1 32 21V13A9 9 0 0 1 41 4Z" fill="currentColor" />
      <path d="M36 37H46A4 4 0 0 1 50 41A4 4 0 0 1 46 45H36A4 4 0 0 1 32 41A4 4 0 0 1 36 37Z" fill="currentColor" />
    </svg>
  )
}

/** A half-filled circle that turns while the agent works. */
function RunningGlyph(): ReactNode {
  return (
    <svg className={css.running} width="16" height="16" viewBox="0 0 20 20" aria-hidden="true">
      <circle cx="10" cy="10" r="7" fill="none" stroke="currentColor" strokeWidth="1.6" />
      <path d="M10 3a7 7 0 0 1 0 14z" fill="currentColor" />
    </svg>
  )
}
